// Package repository persists users in Postgres and refresh sessions in Redis.
package repository

import (
	"context"
	"errors"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/Andas-LV/cargoflow/services/auth/internal/repository/db"
)

var (
	ErrNotFound  = errors.New("not found")
	ErrDuplicate = errors.New("duplicate")
)

const pgUniqueViolation = "23505"

// User is the stored user record (generated by sqlc).
type User = db.User

type Users struct {
	q *db.Queries
}

func NewUsers(pool *pgxpool.Pool) *Users {
	return &Users{q: db.New(pool)}
}

func (r *Users) Create(ctx context.Context, id uuid.UUID, email, passwordHash string) (User, error) {
	u, err := r.q.CreateUser(ctx, db.CreateUserParams{ID: id, Email: email, PasswordHash: passwordHash})
	if pgErr := (*pgconn.PgError)(nil); errors.As(err, &pgErr) && pgErr.Code == pgUniqueViolation {
		return User{}, ErrDuplicate
	}
	return u, err
}

func (r *Users) GetByEmail(ctx context.Context, email string) (User, error) {
	u, err := r.q.GetUserByEmail(ctx, email)
	if errors.Is(err, pgx.ErrNoRows) {
		return User{}, ErrNotFound
	}
	return u, err
}
